CREATE TABLE IF NOT EXISTS "error_analyses" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL, "error_group_id" uuid NOT NULL REFERENCES "error_groups"("id") ON DELETE CASCADE, "requested_by_admin_id" uuid NOT NULL REFERENCES "users"("id"), "model" varchar(160) NOT NULL, "provider" varchar(80) NOT NULL, "prompt_version" varchar(80) NOT NULL, "context_version" varchar(80) NOT NULL, "context_hash" varchar(128) NOT NULL, "input_summary" jsonb NOT NULL, "likely_cause" text NOT NULL, "evidence" jsonb NOT NULL, "investigation_steps" jsonb NOT NULL, "suggested_fix" text NOT NULL, "likely_modules" jsonb NOT NULL, "confidence" varchar(16) NOT NULL, "limitations" jsonb NOT NULL, "created_at" timestamp NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS "idx_error_analyses_group_created" ON "error_analyses" ("error_group_id", "created_at");
CREATE INDEX IF NOT EXISTS "idx_error_analyses_context_hash" ON "error_analyses" ("context_hash");
